def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    total_seconds = 0
    i = 0
    n = len(s)

    while i < n:
        num = 0
        while i < n and s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1

        if num == 0 and (i >= n or not s[i].isalpha()):
            raise ValueError(f"Invalid duration string: {s}")

        if i >= n:
            raise ValueError(f"Missing unit in duration string: {s}")

        unit = s[i]
        i += 1

        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num
        else:
            raise ValueError(f"Invalid unit '{unit}' in duration string: {s}")

    return total_seconds
